"use client"

import React, { useMemo } from "react"
import { Skeleton } from "@heroui/react"

/** Props for {@link PaginationSkeleton}. */
export interface PaginationSkeletonProps {
    /** Number of page-number pill placeholders between prev/next. */
    pageCount?: number
}

/**
 * Loading placeholder for a centered HeroUI {@link Pagination} row.
 *
 * Mirrors the `sm` pagination layout: previous control, page links, next control.
 *
 * @param props.pageCount - Page pill count (defaults to 3).
 */
export const PaginationSkeleton = ({
    pageCount = 3,
}: PaginationSkeletonProps) => {
    const pageIndexes = useMemo(
        () => Array.from({ length: pageCount }, (_, index) => index),
        [pageCount],
    )

    return (
        <div className="flex justify-center">
            <div className="flex flex-wrap items-center justify-center gap-1">
                <Skeleton className="size-8 rounded-lg" />
                {pageIndexes.map((index) => (
                    <Skeleton key={index} className="size-8 rounded-lg" />
                ))}
                <Skeleton className="size-8 rounded-lg" />
            </div>
        </div>
    )
}

import { cn } from "@heroui/react"
import { XIcon } from "@phosphor-icons/react"
import { Typography } from "@/components/atoms/text/Typography"
import { Button, type IconComponent } from "@/components/atoms/buttons/Button"
import { StackH } from "@/components/frames/Stack"

/**
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 * STORYBOOK-LOCAL DESIGN SPEC ΓÇö the target `RemovableToken`. Authored in
 * Storybook (not `src`); synced to `src` later. NO `@/components` imports.
 *
 * Grounded in the hand-rolled "picked company" row in
 * `CompanySection` (`src/components/features/careers/Jobs/JobPostForm/CompanySection/index.tsx`):
 * a bordered `rounded-2xl` flex row ΓÇö a label on the left, a tertiary
 * `Button` (├ù icon + "Change" text) on the right that clears the pick. This
 * composite generalises that ONE hand-rolled row into a reusable
 * selected-item token: any label/icon in, an optional remove (├ù) and/or
 * edit ("Change"-style) affordance out.
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 */

/** Props for the {@link RemovableToken} composite. */
export interface RemovableTokenProps {
    /** Token label content ΓÇö text the composite wraps itself (in `Typography`). */
    label: string
    /**
     * Optional LEADING glyph before the label, passed as a COMPONENT reference
     * (e.g. `icon={FolderIcon}`), never JSX ΓÇö the composite renders it at its own
     * scale (`size-4`) and, being a reference rather than an already-called node,
     * can still call it during `isSkeleton` (unlike a frozen element).
     */
    icon?: IconComponent
    /**
     * Renders a trailing edit affordance ΓÇö a small tertiary `Button` (├ù icon +
     * {@link RemovableTokenProps.editLabel}), mirroring the ground-truth
     * "Change" button that clears a picked company so the user can re-search.
     * Use this when removing the token means "go pick a different one", not
     * "delete it".
     */
    onEdit?: () => void
    /** Label for the edit affordance's button text. Defaults to "Change". */
    editLabel?: string
    /**
     * Renders a trailing COMPACT close (├ù) ΓÇö click it to remove the token
     * outright (no re-pick flow). Own compact scale (size-6 hit, size-4
     * glyph), like a chip's cancel-├ù, not the button-scale edit affordance.
     */
    onRemove?: () => void
    /** Accessible label for the remove (├ù) button. Falls back to "Remove". */
    removeLabel?: string
    /** Disables both affordances and dims the token. */
    isDisabled?: boolean
    /** `true` ΓåÆ render the skeleton mirror (row frame + placeholder bars). */
    isSkeleton?: boolean
}

/**
 * Generic selected-item token: a bordered `rounded-2xl` row holding an
 * optional leading icon + label, with an optional trailing remove (├ù) and/or
 * edit ("Change"-style) affordance. Compact ΓÇö one line, no wrapping content.
 * Presentational; the only callbacks it takes are the two trailing
 * affordances.
 *
 * @param props - {@link RemovableTokenProps}
 */
/** Source-level tier metadata ΓÇö see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "RemovableToken" } as const

/** A bordered row token showing a label with optional remove (x) and edit affordances. */
export const RemovableToken = ({
    label,
    icon: Icon,
    onEdit,
    editLabel = "Change",
    onRemove,
    removeLabel = "Remove",
    isDisabled = false,
    
    isSkeleton = false}: RemovableTokenProps) => {
    // One render path: the row's own frame stays identical whether loading or not;
    // only the trailing affordance's CONTENT differs (a shimmer pill vs the real
    // edit/remove controls) ΓÇö `Button`/`Typography` each draw their own shimmer,
    // this composite only decides which parts show and how many (COMPOSITE-10).
    const trailing = isSkeleton ? (
        <span className="shrink-0"><Button isSkeleton size="sm" /></span>
    ) : onEdit || onRemove ? (
        <StackH
            gap={3}
            classNames={["shrink-0"]}
            items={[
                ...(onEdit
                    ? [() => (
                        <Button variant="tertiary" size="sm" isDisabled={isDisabled} onPress={onEdit} prefixIcon={XIcon} label={editLabel} />
                    )]
                    : []),
                ...(onRemove
                    ? [() => (
                        // Compact chip-scale close ├ù (NOT the button-scale edit
                        // affordance above) ΓÇö a real <button> for a11y.
                        <button
                            type="button"
                            aria-label={removeLabel}
                            disabled={isDisabled}
                            onClick={onRemove}
                            className="inline-flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted outline-none transition hover:bg-default hover:text-foreground focus-visible:ring-2 focus-visible:ring-accent disabled:cursor-not-allowed [&_svg]:size-4"
                        >
                            <XIcon aria-hidden focusable="false" />
                        </button>
                    )]
                    : []),
            ]}
        />
    ) : null

    return (
        <div
            aria-disabled={isDisabled}
            className={cn(
                "flex items-center justify-between gap-3 rounded-2xl border border-default px-3 py-3",
                isDisabled && "opacity-50")}
            data-tier="composite"
            data-component="RemovableToken"
            data-principle="cell-pad"
        >
            <StackH
                gap={3}
                classNames={["min-w-0"]}
                items={[
                    ...(Icon
                        ? [() => (
                            // COMPOSITE owns the size (┬º4) ΓÇö the atom's own scale, not the
                            // caller's. A component reference can still be called during
                            // `isSkeleton` (it's static chrome, not loaded data), so it
                            // always renders ΓÇö no shimmer needed for it either way.
                            <span aria-hidden className="inline-flex shrink-0 [&_svg]:size-4">
                                <Icon />
                            </span>
                        )]
                        : []),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            truncate
                            isSkeleton={isSkeleton}
                            text={label}
                        />
                    ),
                ]}
            />
            {trailing}
        </div>
    )
}

"use client"

import React from "react"
import { useRouter } from "@/i18n/navigation"
import { InlineLink } from "@/components/atoms/navigation/Link"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/** A single footer link: an internal `path` (locale-aware push) OR an external
 *  `href` (mailto / off-site) ΓÇö exactly one is set. */
export interface FooterNavLink {
    /** Stable React key. */
    key: string
    /** Visible label. */
    label: string
    /** Internal route, locale-aware ΓÇö pushed through the i18n router. */
    path?: string
    /** External / mailto href ΓÇö rendered as a plain anchor press. */
    href?: string
}

/** Props for {@link FooterNavColumn}. */
export interface FooterNavColumnProps {
    /** Quiet column heading (e.g. "Explore", "Support"). */
    title: string
    /** Links stacked under the heading. */
    links: ReadonlyArray<FooterNavLink>
}

/**
 * FooterNavColumn ΓÇö one quiet column of the global {@link Footer}: a small muted
 * heading over a vertical stack of links. Internal links (`path`) route through
 * the locale-aware router; external / mailto links (`href`) open via `onPress`.
 *
 * Kept as a layout helper for callers that still want the connected column
 * shape; the live {@link Footer} now composes the starci `FooterLinkColumn`.
 */
export const FooterNavColumn = ({
    title,
    links,
}: FooterNavColumnProps) => {
    const router = useRouter()

    const rows = links.map((link) => () => (
        <InlineLink
            key={link.key}
            label={link.label}
            size="sm"
            onPress={() => {
                if (link.href) {
                    window.location.href = link.href
                    return
                }
                if (link.path) {
                    router.push(link.path)
                }
            }}
        />
    ))

    return (
        <StackV
            identity={{ tier: "layout", component: "FooterNavColumn" }}
            principle="label-field"
            explain="Column title over its link list ΓÇö not title-subtitle, because the title names the group of controls below rather than continuing in one voice."
            items={[
                () => <Typography size="sm" weight="bold" text={title} />,
                () => (
                    <StackV
                        principle="sibling-stack"
                        explain="Same-kind peer stack of link rows ΓÇö not group-boundary, because these are repeating siblings rather than section groups."
                        items={rows}
                    />
                ),
            ]}
        />
    )
}

"use client"

import React from "react"
import { Typography } from "@/components/atoms/text/Typography"
import { ButtonRadioGroup } from "@/components/composites/buttons/ButtonRadioGroup"
import { ShowFrom } from "@/components/frames/ShowFrom"
import { StackH } from "@/components/frames/Stack"
import { useRouter } from "@/i18n/navigation"
import { useNavbarItems } from "../useNavbarItems"

/**
 * Props for {@link NavLinks}.
 */
export type NavLinksProps = Record<string, never>

/**
 * Desktop navbar link group (hidden on small screens).
 *
 * Container: derives its entries + active-route state from the router/locale
 * itself and self-navigates on press. `"use client"` for the hooks + press
 * handlers. `ShowFrom` owns the md visibility switch; `ButtonRadioGroup` owns
 * the pill row (same vocabulary as the starci `Navbar` / `NavLinks` block).
 */
export const NavLinks = () => {
    const router = useRouter()
    const items = useNavbarItems()
    const activePath = items.find((item) => item.isActive)?.path ?? ""

    return (
        <StackH
            identity={{ tier: "layout", component: "NavLinks" }}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            items={[
                () => (
                    <ShowFrom
                        at="md"
                        body={() => (
                            <ButtonRadioGroup
                                items={items.map((item) => ({
                                    value: item.path,
                                    content: <Typography size="sm" text={item.label} />,
                                }))}
                                value={activePath}
                                onChange={(path) => router.push(path)}
                                ariaLabel="Main navigation"
                            />
                        )}
                    />
                ),
            ]}
        />
    )
}

"use client"

import React from "react"
import { cn } from "@heroui/react"
import { useCallback } from "react"
import type { RendererTypeOption } from "@/modules/types/admin-mpeg-dash-test"
import type { VideoRendererType } from "@/modules/types/enums/video-renderer-type"

/** Props for {@link RendererTypeButton}. */
export interface RendererTypeButtonProps {
    /** Option metadata to render. */
    option: RendererTypeOption
    /** Whether this option is currently selected. */
    isActive: boolean
    /** Selects this option's renderer type. */
    onSelect: (type: VideoRendererType) => void
}

/**
 * Single renderer-type selector button (icon + label + description).
 * @param props.option - Option metadata to render.
 * @param props.isActive - Whether this option is the active renderer type.
 * @param props.onSelect - Called with this option's type when pressed.
 */
export const RendererTypeButton = ({
    option,
    isActive,
    onSelect}: RendererTypeButtonProps) => {
    const onPress = useCallback(
        () => onSelect(option.type),
        [onSelect, option.type],
    )

    return (
        <button
            onClick={onPress}
            className={cn(
                "flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-medium transition-all",
                isActive
                    ? `bg-gradient-to-r ${option.color} text-white shadow-lg`
                    : "bg-slate-700/50 text-slate-300 hover:bg-slate-700",
            )}
        >
            {option.icon}
            <div className="text-left">
                <div>{option.label}</div>
                <div className="text-[10px] opacity-70">
                    {option.description}
                </div>
            </div>
        </button>
    )
}

"use client"

import React from "react"
import { Card, CardContent, Input } from "@heroui/react"
import { RENDERER_TYPE_OPTIONS } from "@/modules/utils/admin-mpeg-dash-map"
import { RendererTypeButton } from "./RendererTypeButton"
import type { VideoRendererType } from "@/modules/types/enums/video-renderer-type"
import { Box } from "@/components/frames/Box"

/** Props for {@link ConfigCard}. */
export interface ConfigCardProps {
    /** Current URL value. */
    url: string
    /** Currently selected renderer type. */
    activeType: VideoRendererType
    /** Updates the URL value. */
    onChangeUrl: (value: string) => void
    /** Selects a renderer type. */
    onSelectType: (type: VideoRendererType) => void
}

/**
 * Configuration card: URL input + renderer-type selector buttons.
 * @param props.url - Current URL value.
 * @param props.activeType - Currently selected renderer type.
 * @param props.onChangeUrl - Updates the URL value.
 * @param props.onSelectType - Selects a renderer type.
 */
export const ConfigCard = ({
    url,
    activeType,
    onChangeUrl,
    onSelectType}: ConfigCardProps) => (
    <Card className={"border-slate-700/50 bg-slate-800/50 backdrop-blur-xl"}>
        <CardContent>
            <Box principle="page-pad" className="space-y-3 p-6"
                explain="Page chrome inset ΓÇö not card-padding, because this pads the whole page rather than a nested card surface.">
                <h2 className="text-lg font-semibold text-white">
                    Configuration
                </h2>

                <Input
                    id="mpegdash-url-input"
                    placeholder="https://example.com/stream/manifest.mpd"
                    value={url}
                    onChange={(e) => onChangeUrl(e.target.value)}
                    className="text-white"
                />

                <Box principle="chip-row" className="flex flex-wrap gap-2"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column.">
                    {RENDERER_TYPE_OPTIONS.map((option) => (
                        <RendererTypeButton
                            key={option.type}
                            option={option}
                            isActive={activeType === option.type}
                            onSelect={onSelectType}
                        />
                    ))}
                </Box>
            </Box>
        </CardContent>
    </Card>
)

"use client"

import React from "react"
import { Card, CardContent } from "@heroui/react"
import { useMemo } from "react"
import { RENDERER_TYPE_OPTION_MAP } from "@/modules/utils/admin-mpeg-dash-map"
import { VideoRenderer } from "@/components/blocks/media/VideoRenderer"
import type { VideoRendererType } from "@/modules/types/enums/video-renderer-type"
import { Box } from "@/components/frames/Box"

/** Props for {@link PreviewCard}. */
export interface PreviewCardProps {
    /** URL to preview. */
    url: string
    /** Renderer type used to preview the URL. */
    activeType: VideoRendererType
}

/**
 * Preview card: renders the {@link VideoRenderer} for the entered URL,
 * or a placeholder when no URL is provided.
 * @param props.url - URL to preview.
 * @param props.activeType - Renderer type used to preview the URL.
 */
export const PreviewCard = ({ url, activeType}: PreviewCardProps) => {
    const activeLabel = useMemo(
        () => RENDERER_TYPE_OPTION_MAP[activeType]?.label,
        [activeType],
    )
    const hasUrl = url.trim().length > 0

    return (
        <Card className={"border-separator bg-surface backdrop-blur-xl"}>
            <CardContent>
                <Box principle="cell-pad" className="space-y-3 p-3"
                    explain="Tight cell inset ΓÇö not card-padding, because this sits inside a dense table or list cell rather than a card body.">
                    {/* ps-admin-6: h2 gap-2 ΓÇö block element inside heading invalid; foreign mount ΓÇö teacher-hold */}
                    <h2 data-principle="ps-admin-6" className="text-lg font-semibold text-foreground flex items-center gap-2">
                    Preview
                        <span className="text-xs font-normal text-muted">
                        ({activeLabel})
                        </span>
                    </h2>

                    {hasUrl ? (
                        <VideoRenderer
                            url={url}
                            rendererType={activeType}
                            title="Test video"
                        />
                    ) : (
                        <div className="flex aspect-video items-center justify-center rounded-large border border-dashed border-separator text-sm text-muted">
                        Enter a URL above to preview
                        </div>
                    )}
                </Box>
            </CardContent>
        </Card>
    )
}

"use client"

import React, { useCallback } from "react"
import type { QuickTestUrl } from "@/modules/types/admin-mpeg-dash-test"

/** Props for {@link QuickTestUrlButton}. */
export interface QuickTestUrlButtonProps {
    /** Preset to render. */
    item: QuickTestUrl
    /** Loads the preset's URL + renderer type into the tool. */
    onSelect: (item: QuickTestUrl) => void
}

/**
 * Single quick-test preset row; loads its URL + type when pressed.
 * @param props.item - Preset to render.
 * @param props.onSelect - Called with the preset when pressed.
 */
export const QuickTestUrlButton = ({ item, onSelect}: QuickTestUrlButtonProps) => {
    const onPress = useCallback(
        () => onSelect(item),
        [onSelect, item],
    )

    return (
        <button
            onClick={onPress}
            className={"w-full rounded-lg bg-slate-700/30 px-3 py-2 text-left text-xs text-slate-300 transition-colors hover:bg-slate-700/60"}
        >
            <span className="font-medium text-white">
                {item.label}
            </span>
            <br />
            <span className="text-slate-500 break-all">
                {item.url}
            </span>
        </button>
    )
}

"use client"

import React from "react"
import { Card, CardContent } from "@heroui/react"
import { QUICK_TEST_URLS } from "@/modules/utils/admin-mpeg-dash-quick-urls"
import { QuickTestUrlButton } from "./QuickTestUrlButton"
import type { QuickTestUrl } from "@/modules/types/admin-mpeg-dash-test"
import { Box } from "@/components/frames/Box"

/** Props for {@link QuickTestUrls}. */
export interface QuickTestUrlsProps {
    /** Loads a preset's URL + renderer type into the tool. */
    onSelect: (item: QuickTestUrl) => void
}

/**
 * Quick test URLs card: preset buttons that load a URL + renderer type.
 * @param props.onSelect - Called with the chosen preset.
 */
export const QuickTestUrls = ({ onSelect}: QuickTestUrlsProps) => (
    <Card className={"border-slate-700/50 bg-slate-800/50 backdrop-blur-xl"}>
        <CardContent>
            <Box principle="page-pad" className="space-y-3 p-6"
                explain="Page chrome inset ΓÇö not card-padding, because this pads the whole page rather than a nested card surface.">
                <h2 className="text-sm font-medium text-slate-400">
                    Quick Test URLs
                </h2>
                <div className="space-y-2">
                    {QUICK_TEST_URLS.map((item) => (
                        <QuickTestUrlButton
                            key={item.url}
                            item={item}
                            onSelect={onSelect}
