"use client"

import React, { useCallback, useEffect, useMemo } from "react"
import { useTranslations } from "next-intl"
import { _ChatPane } from "./component"
import { PublicationEvent } from "@/hooks/socketio/enums/publication-event"
import { SubscriptionEvent } from "@/hooks/socketio/enums/subscription-event"
import { communityChatSocketIoEventEmitter } from "@/hooks/socketio/useCommunityChatSocketIoLifecycle"
import { useCommunityChatSocketIo } from "@/hooks/socketio/useCommunityChatSocketIo"
import { useMutateSendChatMessageSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSendChatMessageSwr"
import { useQueryChatMessagesSwr } from "@/hooks/swr/api/graphql/queries/useQueryChatMessagesSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"

/** Props for {@link ChatPane}. */
export interface ChatPaneProps {
    /**
     * Conversation whose messages are shown + sent to. Omitted/null ΓåÆ shimmer
     * mirror of the pane (message list + composer) while the active id resolves.
     */
    conversationId?: string | null
}

type ChatPaneLiveProps = {
    conversationId: string
}

/**
 * Live connected pane ΓÇö hooks only run when a conversation id is known.
 */
const ChatPaneLive = ({ conversationId }: ChatPaneLiveProps) => {
    const t = useTranslations()
    const runGraphQL = useGraphQLWithToast()
    const socket = useCommunityChatSocketIo()

    const { data, isLoading, error, mutate } = useQueryChatMessagesSwr(conversationId)
    const { trigger: sendMessage, isMutating } = useMutateSendChatMessageSwr()

    // server returns newest-first; render oldestΓåÆnewest so the latest sits at the bottom
    const messages = useMemo(
        () => [...(data?.items ?? [])].reverse(),
        [data],
    )

    // join the conversation room (and re-join on reconnect)
    useEffect(() => {
        const subscribe = () => {
            socket.emit(PublicationEvent.SubscribeCommunityChat, {
                data: {
                    conversationId,
                },
            })
        }
        if (socket.connected) {
            subscribe()
        }
        socket.on("connect", subscribe)
        return () => {
            socket.off("connect", subscribe)
        }
    }, [socket, conversationId])

    // refetch whenever a realtime message arrives for THIS conversation
    useEffect(() => {
        const handler = (message: { data?: { conversationId?: string } }) => {
            // ignore events for other conversations sharing the same socket
            if (message?.data?.conversationId !== conversationId) {
                return
            }
            void mutate()
        }
        communityChatSocketIoEventEmitter.on(SubscriptionEvent.ChatMessageCreated, handler)
        return () => {
            communityChatSocketIoEventEmitter.off(SubscriptionEvent.ChatMessageCreated, handler)
        }
    }, [conversationId, mutate])

    /** Send one message (toast-wrapped), then refresh the list on success. */
    const onSend = useCallback(async (trimmedBody: string) => {
        const ok = await runGraphQL(async () => {
            const result = await sendMessage({
                conversationId,
                body: trimmedBody,
            })
            return result.data!.sendChatMessage
        })
        if (ok) {
            await mutate()
        }
        return ok
    }, [conversationId, sendMessage, runGraphQL, mutate])

    return (
        <_ChatPane
            // first load, nothing in hand ΓåÆ shimmer (loading-and-skeleton.md)
            isSkeleton={isLoading && messages.length === 0}
            isEmpty={messages.length === 0}
            // only a settled fetch error with nothing cached to show reaches the block
            error={messages.length === 0 ? error : undefined}
            onRetry={() => void mutate()}
            messages={messages}
            isSending={isMutating}
            onSend={onSend}
            labels={{
                empty: t("community.chat.empty"),
                error: t("community.chat.error"),
                retry: t("community.retry"),
                placeholder: t("community.chat.placeholder"),
                send: t("community.chat.send"),
            }}
        />
    )
}

/**
 * `ChatPane` ΓÇö the connected half (see `tiers/split.md`) of one chat
 * conversation pane: fetches the conversation's messages, joins its
 * Socket.IO room and refetches on every new message (so messages from
 * others appear in real time), and resolves every label before handing
 * them to the presentational {@link _ChatPane}.
 *
 * @param props - {@link ChatPaneProps}
 */
export const ChatPane = ({ conversationId }: ChatPaneProps) => {
    const t = useTranslations()

    // Wait for an active conversation id ΓÇö same shape as the live pane via
    // intrinsic `isSkeleton` (no parallel public skeleton export).
    if (!conversationId) {
        return (
            <_ChatPane
                isSkeleton
                isEmpty={false}
                messages={[]}
                isSending={false}
                onSend={async () => false}
                labels={{
                    empty: t("community.chat.empty"),
                    error: t("community.chat.error"),
                    retry: t("community.retry"),
                    placeholder: t("community.chat.placeholder"),
                    send: t("community.chat.send"),
                }}
            />
        )
    }
    return <ChatPaneLive conversationId={conversationId} />
}

"use client"

import React, { useMemo, useState } from "react"
import { Button } from "@heroui/react"
import { UsersThreeIcon } from "@phosphor-icons/react"
import type { Key } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { ChatPane } from "./ChatPane"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { PageContainer } from "@/components/blocks/layout/PageContainer"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { useAuthenticationOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useQueryCommunityChatConversationSwr } from "@/hooks/swr/api/graphql/queries/useQueryCommunityChatConversationSwr"
import { useQueryMyFounderConversationSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFounderConversationSwr"
import { useAppSelector } from "@/redux/hooks"
import { pathConfig } from "@/resources/path"
import { StackV } from "@/components/frames/Stack"

/** Which conversation the chat surface is showing. */
type ChatTab = "community" | "founder"

/**
 * Community chat surface: a toggle between the global community room and the
 * private founder DM, with the active conversation's message pane below. Member-
 * only ΓÇö signed-out users see a prompt; the server enforces the membership gate.
 */
export const CommunityChatPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    const authentication = useAuthenticationOverlayState()
    const [tab, setTab] = useState<ChatTab>("community")

    const communityConversationSwr = useQueryCommunityChatConversationSwr()
    const founderConversationSwr = useQueryMyFounderConversationSwr()

    // the SWR handle for the active tab ΓÇö chat reads are member-only, so a
    // signed-in non-member either errors (membership gate) or resolves to null.
    const activeConversationSwr = tab === "community"
        ? communityConversationSwr
        : founderConversationSwr

    // the conversation id for the active tab (undefined until resolved)
    const conversationId = activeConversationSwr.data?.id
    // still resolving: only the initial load, before either an id or a terminal
    // (error / null) is known ΓÇö this is what the skeleton is allowed to cover.
    const isResolving = activeConversationSwr.isLoading && !activeConversationSwr.data
    // the query settled but yielded no conversation for the active tab: the
    // membership gate rejected a signed-in non-member (or the read failed).
    const membersOnly = !isResolving && !conversationId

    const tabs = useMemo(
        () => [
            { key: "community", label: t("community.chat.communityRoom") },
            { key: "founder", label: t("community.chat.founderDm") },
        ],
        [t],
    )

    return (
        <PageContainer>
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <PageHeader
                            title={t("community.chat.title")}
                            description={t("community.chat.description")}
                        />
                    ),
                    () => (authenticated ? (
                        <StackV gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={[
                                () => (
                                    <TabsCard
                                        leftTabs={{
                                            items: tabs,
                                            selectedKey: tab,
                                            ariaLabel: t("community.chat.tabsAria"),
                                            onSelectionChange: (key: Key) => setTab(String(key) as ChatTab),
                                        }}
                                    />
                                ),
                                () => (conversationId ? (
                                    <ChatPane key={conversationId} conversationId={conversationId} />
                                ) : membersOnly ? (
                                // Signed-in but the membership gate rejected this read (or it
                                // failed): a non-member must not sit on a perpetual skeleton ΓÇö
                                // surface a members-only terminal with an upsell to membership.
                                    <EmptyState
                                        icon={UsersThreeIcon}
                                        title={t("community.chat.membersOnly")}
                                        description={t("community.chat.membersOnlyDescription")}
                                        action={() => (
                                            <Button
                                                variant="primary"
                                                size="sm"
                                                onPress={() => router.push(
                                                    pathConfig().locale(locale).profile().membership().build(),
                                                )}
                                            >
                                                {t("community.chat.viewMembership")}
                                            </Button>
                                        )}
                                    />
                                ) : (
                                // 2026-07-12: was a bare "loadingΓÇª" caption while the active
                                // conversation id resolves ΓÇö mirror the real pane's shape
                                // (message list + composer) so the tab switch/first load
                                // doesn't jump into a differently-shaped panel afterward.
                                    <ChatPane />
                                )),
                            ]} />
                    ) : (
                        <EmptyState
                            title={t("community.chat.signInRequired")}
                            action={() => (
                                <Button
                                    variant="primary"
                                    size="sm"
                                    onPress={() => authentication.open()}
                                >
                                    {t("nav.signIn")}
                                </Button>
                            )}
                        />
                    )),
                ]} />
        </PageContainer>
    )
}

