                gap={2}
                principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                items={[
                    () => (
                        <Button
                            variant="primary"
                            size="lg"
                            classNames={["w-full"]}
                            label={t("course.continueLearning")}
                            suffixIcon={ArrowRightIcon}
                            onPress={onContinueLearning}
                        />
                    ),
                ]}
            />
        )
    }

    return (
        <StackV
            identity={{ tier: "page", component: "CourseCtaButtons" }}
            gap={2}
            principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
            items={[
                () => (
                    <Button
                        variant="primary"
                        size="lg"
                        classNames={["w-full"]}
                        label={t("course.enroll")}
                        suffixIcon={ArrowRightIcon}
                        onPress={onEnroll}
                    />
                ),
                ...(course ? [
                    () => (
                        <AddToCartButton
                            course={course}
                            isEnrolled={isEnrolled}
                            variant="secondary"
                            fullWidth
                        />
                    ),
                ] : []),
                // "Try free" is the ACQUISITION entry for a non-payer ΓÇö a peer secondary
                // CTA (not buried as quiet tertiary), so the funnel's front door is visible.
                // No trailing arrow: arrow marks the ONE primary CTA per surface
                // (button.md ┬º2) ΓÇö "Enroll" above already carries it.
                () => (
                    <Button
                        variant="secondary"
                        size="lg"
                        classNames={["w-full"]}
                        label={t("course.tryLearning")}
                        onPress={onTryLearning}
                    />
                ),
            ]}
        />
    )
}

"use client"

import React from "react"
import {
    Button,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    ArrowRightIcon,
    GraduationCapIcon,
} from "@phosphor-icons/react"
import {
    usePricingRows,
} from "@/hooks/usePricingRows"
import {
    useCourseEnrollment,
} from "@/hooks/useCourseEnrollment"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StickyBottomBar } from "@/components/blocks/layout/StickyBottomBar"
import { useAppSelector } from "@/redux/hooks"
import { useQueryCoursePricePreviewSwr } from "@/hooks/swr/api/graphql/queries/useQueryCoursePricePreviewSwr"
import { StackH } from "@/components/frames/Stack"

/** Props for {@link CourseMobileEnrollBar}. */
export type CourseMobileEnrollBarProps = Record<string, never>

/**
 * Mobile-only sticky bottom bar (md:hidden): the active price + a single primary
 * action that's always reachable while scrolling the landing on a phone. Reuses
 * the {@link StickyBottomBar} block chrome + the shared pricing / enrollment hooks.
 */
export const CourseMobileEnrollBar = () => {
    const t = useTranslations()
    const { active } = usePricingRows()
    const { isEnrolled, onEnroll, onContinueLearning } = useCourseEnrollment()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    // viewer's loyalty price (matches the rail / catalog) ΓÇö fall back to phase price.
    const { data: preview, isLoading: previewLoading } = useQueryCoursePricePreviewSwr(courseId ?? null)
    const hasLoyalty = preview != null && preview.discountPercent > 0
    // same jump as CoursePricingRail (2026-07-12): don't flash the static price
    // before the loyalty preview resolves ΓÇö skeleton the price line instead.
    const previewPending = previewLoading && !preview

    return (
        <StickyBottomBar>
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                justify="between" align="center" items={[
                    () => (previewPending ? (
                        <Skeleton.Typography type="body" width="1/4" />
                    ) : hasLoyalty && preview ? (
                        <PriceTagInline
                            discounted={preview.discountedPriceVnd}
                            original={preview.originalPriceVnd}

                        />
                    ) : active ? (
                        <PriceTagInline
                            discounted={active.priceVnd}
                            original={active.listPriceVnd}

                        />
                    ) : null),
                    () => (isEnrolled ? (
                        <Button variant="primary" onPress={onContinueLearning}>
                            <GraduationCapIcon className="size-5" />
                            {t("course.continueLearning")}
                        </Button>
                    ) : (
                        <Button variant="primary" onPress={onEnroll}>
                            {t("course.enroll")}
                            <ArrowRightIcon className="size-5" />
                        </Button>
                    )),
                ]} />
        </StickyBottomBar>
    )
}

"use client"

import React from "react"
import {
    useTranslations,
} from "next-intl"
import {
    CheckCircleIcon,
    CircleIcon,
} from "@phosphor-icons/react"
import {
    PHASE_LABEL_KEY,
} from "@/modules/utils/course-detail"
import type {
    CoursePriceRow,
} from "@/modules/types/course-detail"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH } from "@/components/frames/Stack"

/** Props for {@link PhaseRow}. */
export interface PhaseRowProps {
    /** One formatted pricing-phase row (list-item data prop). */
    row: CoursePriceRow
}

/**
 * One step in the price ladder ΓÇö a single signal per row, no chip soup: a state
 * dot (sold-out Γ£ô / current ΓùÅ / upcoming Γùï) + the phase name, and on the right
 * either a state label (sold-out / open now) or the phase price. The current
 * price + scarcity + discount live ONCE in the rail headline, so the current row
 * shows no price here.
 *
 * @param props - {@link PhaseRowProps}
 */
export const PhaseRow = ({ row }: PhaseRowProps) => {
    const t = useTranslations()

    return (
        <Box identity={{ tier: "page", component: "PhaseRow" }}>
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                justify="between" align="center" items={[
                    () => (
                        <StackH gap={3} principle="identity"
                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                            classNames={["min-w-0"]} align="center" items={[
                                () => (row.soldOut ? (
                                    <CheckCircleIcon aria-hidden focusable="false" className="size-4 shrink-0 text-muted" />
                                ) : row.isActive ? (
                                    <CircleIcon aria-hidden focusable="false" weight="fill" className="size-4 shrink-0 text-accent-soft-foreground" />
                                ) : (
                                    <CircleIcon aria-hidden focusable="false" className="size-4 shrink-0 text-foreground" />
                                )),
                                () => (
                                    <Typography
                                        size="sm"
                                        weight={row.isActive ? "semibold" : undefined}
                                        color={row.soldOut ? "muted" : row.isActive ? "accent-soft" : "default"}
                                        truncate
                                        text={t(PHASE_LABEL_KEY[row.phase])}
                                    />
                                ),
                            ]} />
                    ),
                    () => (row.soldOut ? (
                        <Typography size="xs" color="muted" text={t("courseLanding.soldOut")} />
                    ) : row.isActive ? (
                        <Typography size="xs" color="accent-soft" text={t("courseLanding.currentOpen")} />
                    ) : (
                        <Typography size="sm" weight="medium" text={row.formattedPrice} />
                    )),
                ]} />
        </Box>
    )
}

"use client"

import React from "react"
import {
    Card,
    CardContent,
    Separator,
    Typography,
    cn,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    CourseCtaButtons,
} from "../CourseCtaButtons"
import {
    usePricingRows,
} from "@/hooks/usePricingRows"
import {
    PHASE_LABEL_KEY,
} from "@/modules/utils/course-detail"
import {
    PhaseRow,
} from "./PhaseRow"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { CoverImage } from "@/components/blocks/media/CoverImage"
import { PriceTagProminent } from "@/components/blocks/commerce/PriceTag"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { useAppSelector } from "@/redux/hooks"
import { useQueryCoursePricePreviewSwr } from "@/hooks/swr/api/graphql/queries/useQueryCoursePricePreviewSwr"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link CoursePricingRail}. */
export type CoursePricingRailProps = WithClassNames<undefined>

/**
 * The single sticky purchase card (right column): cover thumbnail ΓåÆ headline price
 * + one discount + one scarcity line ΓåÆ a compact phase ladder (state per row, no
 * chip soup) ΓåÆ the CTA cluster ΓåÆ enrolled-count social proof. This is the ONLY buy
 * box on the page (the hero carries no price/CTA). Self-contained (pricing hook +
 * redux).
 *
 * @param props - optional className (placement only).
 */

export const CoursePricingRail = ({ className }: CoursePricingRailProps) => {
    const t = useTranslations()
    const { rows, active } = usePricingRows()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const title = useAppSelector((state) => state.course.entity?.title)
    const coverImageUrl = useAppSelector((state) => state.course.entity?.coverImageUrl)
    const enrollmentCount = useAppSelector((state) => state.course.entity?.enrollmentCount) ?? 0

    // viewer's loyalty price (same source as the catalog / payment) ΓÇö overrides the
    // phase headline so the price stays identical everywhere. Guests ΓåÆ no preview ΓåÆ phase.
    const { data: preview, isLoading: previewLoading } = useQueryCoursePricePreviewSwr(courseId ?? null)
    const hasLoyalty = preview != null && preview.discountPercent > 0
    // 2026-07-12: authenticated viewers briefly see the STATIC phase price before
    // the loyalty preview resolves, then it silently swaps ΓÇö a jump on the buy box's
    // headline price. Skeleton the price line instead of flashing the wrong number.
    const previewPending = previewLoading && !preview

    return (
        <div className={cn("@app-md:sticky @app-md:top-[88px] @app-md:self-start", className)}>
            <Card>
                <CardContent>
                    <StackV gap={5} principle="group-boundary"
                        explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            () => <CoverImage src={coverImageUrl} alt={title ?? ""} />,

                            // headline: price + ONE discount + ONE scarcity line.
                            // When the viewer has a loyalty discount, the headline is THEIR price
                            // (struck phase price + loyalty chip); otherwise the active phase price.
                            () => (
                                <StackV gap={3} principle="sibling-stack"
                                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={[
                                        () => (
                                            <StackH gap={3} principle="value-row"
                                                explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                                align="center" at="sm" items={[
                                                    // single-source PriceTag ΓÇö loyalty price when the viewer has one,
                                                    // else the active phase price (struck vs list). USD line stays beside it.
                                                    () => (previewPending ? (
                                                        <Skeleton.Typography type="h3" width="1/3" />
                                                    ) : hasLoyalty && preview ? (
                                                        <PriceTagProminent
                                                            discounted={preview.discountedPriceVnd}
                                                            original={preview.originalPriceVnd}

                                                            breakdown={{
                                                                phase: preview.phasePriceVnd,
                                                                loyaltyPercent: preview.discountPercent,
                                                            }}
                                                        />
                                                    ) : active ? (
                                                        <PriceTagProminent
                                                            discounted={active.priceVnd}
                                                            original={active.listPriceVnd}

                                                            breakdown={{
                                                                phase: active.priceVnd,
                                                                loyaltyPercent: 0,
                                                            }}
                                                        />
                                                    ) : null),
                                                    () => (active?.formattedPriceUsd ? (
                                                        <Typography type="body-sm" color="muted">
                                                            {active.formattedPriceUsd}
                                                        </Typography>
                                                    ) : null),
                                                ]} />
                                        ),
                                        () => (active?.slotAvailable != null ? (
                                            <Typography type="body-sm" className="text-warning-soft-foreground">
                                                {t("courseLanding.slotsLeftPhase", {
                                                    count: active.slotAvailable,
                                                    phase: t(PHASE_LABEL_KEY[active.phase]),
                                                })}
                                            </Typography>
                                        ) : null),
                                    ]} />
                            ),

                            // price ladder ΓÇö minimal, current highlighted, future prices = urgency
                            () => (rows.length > 0 ? (
                                <>
                                    <Separator />
                                    <StackV gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={rows.map((row) => () => <PhaseRow key={row.id} row={row} />)}  />
                                    <Separator />
                                </>
                            ) : null),

                            () => <CourseCtaButtons />,
                            () => (
                                <Typography type="body-xs" color="muted" align="center">
                                    {t("course.usersEnrolled", { count: enrollmentCount })}
                                </Typography>
                            ),
                        ]} />
                </CardContent>
            </Card>
        </div>
    )
}
